theory:
**Множественное встраивание интерфейсов:**
- Встраивание `io.Reader` и `io.Closer` автоматически делает структуру совместимой с `io.ReadCloser`;
- Позволяет собирать композитные интерфейсные контракты.

code_blocks.code:
package main

import (
	"fmt"
	"io"
	"strings"
)

type DummyCloser struct{}

func (DummyCloser) Close() error {
	fmt.Println("Поток успешно закрыт")
	return nil
}

type StreamWrapper struct {
	io.Reader
	io.Closer
}

func ProcessStream(rc io.ReadCloser) {
	defer rc.Close()
	buf := make([]byte, 32)
	n, _ := rc.Read(buf)
	fmt.Printf("Прочитано: %q\n", string(buf[:n]))
}

func main() {
	stream := StreamWrapper{
		Reader: strings.NewReader("Бинарные данные сессии"),
		Closer: DummyCloser{},
	}

	// StreamWrapper автоматически реализует io.ReadCloser:
	ProcessStream(stream)
}

theory:
**Паттерн обратного вызова (Callback Pattern) в структурах:**
- Поле структуры может иметь функциональный тип `OnClick func(string)`;
- Позволяет динамически настраивать реакцию объекта на события в рантайме (паттерн Observer / Event Listener).

code_blocks.code:
package main

import "fmt"

type Button struct {
	Label   string
	OnClick func(label string) // Поле-коллбэк
}

func (b *Button) Click() {
	if b.OnClick != nil {
		b.OnClick(b.Label)
	} else {
		fmt.Printf("Кнопка %q нажата, но обработчик не назначен\n", b.Label)
	}
}

func main() {
	submitBtn := &Button{
		Label: "Оплатить заказ",
		OnClick: func(name string) {
			fmt.Printf("⚡ СОБЫТИЕ: Инициирована транзакция для кнопки %q\n", name)
		},
	}

	submitBtn.Click()
}

